import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"Add Observability to Your Business","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/observability","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/observability.md","filePath":"en/tutorials/observability.md"}'),o={name:"en/tutorials/observability.md"};function i(n,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="add-observability-to-your-business" tabindex="-1">Add Observability to Your Business <a class="header-anchor" href="#add-observability-to-your-business" aria-label="Permalink to &quot;Add Observability to Your Business&quot;">​</a></h1><p>Goal: trace your HTTP request through Jobs, storage and audit without making telemetry a commit dependency. Start with a <a href="./first-request">public API</a>; background work uses <a href="./document-exports">Jobs</a>, durable success uses <a href="./audit-history">Audit</a>.</p><h2 id="start-optional-telemetry-services" tabindex="-1">Start Optional Telemetry Services <a class="header-anchor" href="#start-optional-telemetry-services" aria-label="Permalink to &quot;Start Optional Telemetry Services&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-observability</span></span></code></pre></div><p>This starts normal development services plus Collector, Tempo, Loki, Prometheus and Grafana. Sign in as an Owner or Admin and open Settings → Monitoring (<code>/settings?section=monitoring</code>); open SaaS operations in <a href="http://127.0.0.1:13300" target="_blank" rel="noreferrer">Grafana</a> for detailed queries. The link uses the <code>.env.example</code> port; use the startup output when overriding ports. Anonymous read-only local Grafana access and loopback ports are not production authentication. Normal <code>just dev</code> omits this stack.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/compose.observability.yaml" target="_blank" rel="noreferrer">Compose overlay</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/deploy/observability/collector.yaml" target="_blank" rel="noreferrer">Collector configuration</a> define actual services/data sources. Configure TELEMETRY_HTTP_PORT/TEMPO_PORT/LOKI_PORT/PROMETHEUS_PORT/GRAFANA_PORT for conflicts. Use <code>just observability-up / observability-validate / observability-down</code> independently; starting Collector does not enable export in existing processes. Restart applications or explicitly configure TELEMETRY_ENDPOINT/TELEMETRY_LOG_DIRECTORY.</p><h2 id="check-runtime-status-in-settings" tabindex="-1">Check Runtime Status in Settings <a class="header-anchor" href="#check-runtime-status-in-settings" aria-label="Permalink to &quot;Check Runtime Status in Settings&quot;">​</a></h2><p>Monitoring has Overview, Requests &amp; performance, Background jobs, and Collection &amp; alerts tabs with a last-15-minutes or last-hour selector. The question mark beside each metric explains its units and meaning on hover, keyboard focus, or click; the page keeps only essential guidance. P95 means 95% of requests complete within that duration, and server error rate counts only 5xx responses. Background jobs distinguish the current queue, execution attempts, and terminal failures: retries are not a count of failed jobs.</p><p>The application reads summaries through the administrator endpoint <code>GET /api/v1/system/monitoring?window_minutes=15</code>; the window also accepts <code>60</code>. Browsers do not connect to Prometheus. Request statistics exclude health checks and monitoring endpoints so automatic refresh cannot obscure business traffic. The current job queue is independent of metric collection and remains available without Prometheus.</p><p>Disabled collection, waiting for data, collecting, stale data, and query failures have distinct states; missing samples never display as zero errors or healthy. After startup, wait for at least two scrapes and make requests on business pages before returning to inspect trends. A Collector can still serve cached metrics, so API and Worker update the timestamp in <code>saas_telemetry_heartbeat_seconds{service=~&quot;saas-api|saas-worker&quot;}</code> on every export. This requires no user traffic; data without an update for over 180 seconds is stale.</p><p>Three deployment settings connect different endpoints:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose and local startup behavior</th></tr></thead><tbody><tr><td><code>MONITORING_PROMETHEUS_URL</code></td><td>Base URL used by API and Worker to query metrics; <code>just dev-observability</code> derives a host address from <code>PROMETHEUS_PORT</code>.</td></tr><tr><td><code>MONITORING_WORKER_URL</code></td><td>Base URL used by API to check Worker readiness; development scripts derive a host address from <code>WORKER_PORT</code>. Production Compose uses the internal address <code>http://worker:3001</code>.</td></tr><tr><td><code>MONITORING_GRAFANA_URL</code></td><td>Browser-facing link to detailed dashboards; <code>just dev-observability</code> derives a host address from <code>GRAFANA_PORT</code>.</td></tr></tbody></table><p>Explicit addresses take priority over derived values. Prometheus and Worker accept HTTP(S) base addresses without paths, credentials, query parameters, or fragments. Grafana may have a path and requires HTTPS except on localhost/loopback, also without credentials, query parameters, or fragments. API and Worker read environment settings at startup, so restart both after changes. Saving on the page persists alert rules; it does not install or start monitoring services. In production, configure internal connections to the operator&#39;s collection/query services and authenticated browser access to Grafana. Prometheus and Worker do not need public ports.</p><h2 id="configure-in-app-alerts" tabindex="-1">Configure In-App Alerts <a class="header-anchor" href="#configure-in-app-alerts" aria-label="Permalink to &quot;Configure In-App Alerts&quot;">​</a></h2><p>Collection &amp; alerts saves an error-rate threshold and duration. Alerts default to disabled, with a 1% threshold sustained for 5 minutes. Worker evaluates independently every 30 seconds, regardless of <code>JOB_MAINTENANCE_SECS</code>. It uses requests from the last 5 minutes and requires at least 100 requests to avoid low-traffic false positives from an isolated failure. A sustained breach sends an alert to currently active Owners/Admins; confirmed recovery sends a recovery notification. Rules are persisted and continue to run after the browser closes.</p><p>Send test notification sends only to the administrator performing the action. View result opens monitoring from their inbox. This checks in-app notification delivery, does not mean the threshold fired, and does not notify every member. Rule endpoints are <code>GET/PUT /api/v1/system/monitoring/alerts</code>; testing uses <code>POST /api/v1/system/monitoring/alerts/test</code>. Mutations and tests require a Session, administrator permission, and CSRF validation. This rule does not send email, SMS, or external notifications.</p><p>For a failure check, run <code>just observability-down</code> in another local development terminal. Monitoring should report collection or query failure instead of zero errors; missing or stale samples must not resolve an existing alert. Run <code>just observability-up</code> to restore services and wait for fresh samples before evaluating health. In-app alerts depend on Worker, the database, and inbox access. Availability checks outside the deployment must notify operators when the whole host or Worker stops.</p><h2 id="reuse-public-wiring" tabindex="-1">Reuse Public Wiring <a class="header-anchor" href="#reuse-public-wiring" aria-label="Permalink to &quot;Reuse Public Wiring&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/http.rs" target="_blank" rel="noreferrer">HTTP context</a> creates request IDs/spans, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Jobs enqueue</a> persists safe parent/correlation/actor, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker</a> creates an independent attempt span and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">storage adapter</a> records finite operations/outcomes. Your Domain need not depend on OTel.</p><p>Responses carry <code>x-request-id / x-trace-id</code> for Tempo/Loki correlation. HTTP spans can end before queued work starts; Worker restores W3C parent from the database. Restart/retry creates fresh spans rather than reusing IDs. traceparent is telemetry only, never authorization. Baggage/tracestate/raw URI/full headers are not persisted.</p><p>Add only necessary static events in your use case; call/field excerpt:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tracing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tickets.export.requested&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;business request accepted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Record at the actual success point and actor only after authorization. Exclude bodies, tokens, passwords, signed URLs and raw AWS/Redis errors. Keep route/kind/operation/outcome labels finite. User/Job/resource/trace IDs are correlation fields, never metric labels.</p><h2 id="correlate-with-durable-results" tabindex="-1">Correlate with Durable Results <a class="header-anchor" href="#correlate-with-durable-results" aria-label="Permalink to &quot;Correlate with Durable Results&quot;">​</a></h2><p>Replace the example value with your full trace ID:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{service_name=~&quot;saas-api|saas-worker&quot;} |= &quot;YOUR_TRACE_ID&quot;</span></span>
<span class="line"><span>sum by (route, status) (rate(saas_http_requests_total[5m]))</span></span>
<span class="line"><span>sum by (kind, outcome) (rate(saas_jobs_attempts_total[5m]))</span></span></code></pre></div><p>The first line is LogQL, the others PromQL. JSON context lives in span/spans and event fields in fields rather than all at top level. Rates need at least two scrapes; Histogram P95 interpolates buckets. A transient attempt is not terminal Job failure. Compare task batch/history, business result and Audit; an observed span does not prove commit.</p><h2 id="telemetry-failure-cannot-backpressure-business" tabindex="-1">Telemetry Failure Cannot Backpressure Business <a class="header-anchor" href="#telemetry-failure-cannot-backpressure-business" aria-label="Permalink to &quot;Telemetry Failure Cannot Backpressure Business&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/telemetry/mod.rs" target="_blank" rel="noreferrer">Platform telemetry</a> defaults to span queue 512, batch 64 and lossy log queue 1024; overflow drops observations. OTLP has a 1-second total budget without automatic retry. Collector has a memory limiter, finite queues and at most 10 seconds retry. Collector failure neither fails database readiness nor reexecutes business.</p><p>Empty TELEMETRY_ENDPOINT disables export; current support is local HTTP loopback/collector service name. Invalid parents start fresh traces; upstream unsampled traces may return IDs without exported records. Output accepts only controlled project saas_* targets, including TRACE level, without enabling third-party secret logs.</p><p>Shutdown drains business first, then closes providers finitely. Trace has 2 seconds, current metrics reader 5 seconds and logs a finite wait; data loss is allowed. Hourly app files retain at most 24 files, not an exact disk quota. Prometheus/Loki retention is asynchronous and development volume capacity needs monitoring. Define production budgets/retention explicitly.</p><h2 id="verify-integration" tabindex="-1">Verify Integration <a class="header-anchor" href="#verify-integration" aria-label="Permalink to &quot;Verify Integration&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_outage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitoring</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitoring_alerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/telemetry.rs" target="_blank" rel="noreferrer">Public checks</a> capture real OTLP protobuf and drive HTTP/Worker/storage to verify parents, actors, audit and finite labels. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/telemetry_outage.rs" target="_blank" rel="noreferrer">Outage</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/telemetry_shutdown.rs" target="_blank" rel="noreferrer">shutdown</a> prove blocked export still allows business, bounded backlog and exit.</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/monitoring.rs" target="_blank" rel="noreferrer">Monitoring HTTP checks</a> cover administrator permissions, collection states, and query summaries. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/monitoring_alerts.rs" target="_blank" rel="noreferrer">Alert checks</a> cover persisted rules, in-app test delivery, and sustained failures/recovery.</p><p>Provide matching HTTP/job-result and telemetry-query scenarios for your business. Continue with <a href="./single-machine-production">production</a>.</p><p>For telemetry wiring changes, <code>node scripts/knowledge-observability-smoke.mjs</code> queries real Tempo/Loki/Prometheus/Grafana/Audit in isolation and retains safe IDs. This smoke belongs to the Knowledge reference. See <a href="./perf-gates">performance budgets</a> for capacity validation.</p><hr><p>Source version：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/19-observability.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,40)])])}const b=t(o,[["render",i]]);export{h as __pageData,b as default};
